import pytest
from candidate import count_distinct_characters

def test_count_distinct_characters_normal_case():
    assert count_distinct_characters('xyzXYZ') == 3

def test_count_distinct_characters_mixed_case():
    assert count_distinct_characters('Jerry') == 4

def test_count_distinct_characters_empty_string():
    assert count_distinct_characters('') == 0

def test_count_distinct_characters_with_numbers():
    assert count_distinct_characters('123ABCabc') == 6

def test_count_distinct_characters_with_special_characters():
    assert count_distinct_characters('!@#abcABC') == 6

def test_count_distinct_characters_with_whitespace():
    assert count_distinct_characters(' abc') == 4

def test_count_distinct_characters_repeated_characters():
    assert count_distinct_characters('Mississippi') == 5

def test_count_distinct_characters_all_same_characters():
    assert count_distinct_characters('aaaa') == 1

def test_count_distinct_characters_case_sensitive():
    assert count_distinct_characters('Mississippi') == 7
